// QM SEO-Stichprobe: Status, H1, title, description, canonical, hreflang, robots, JSON-LD
const BASE = "http://127.0.0.1:3100";
const pages = [
  "/", "/de", "/at", "/ch", "/en",
  "/quellen", "/de/quellen",
  "/projektboerse", "/en/projektboerse",
  "/rechner/flaechenpass", "/en/rechner/flaechenpass",
  "/at/energiegemeinschaften", "/ch/freiflaeche",
  "/marktdaten", "/de/marktdaten/fristen", "/en/marktdaten/fristen",
  "/kommunen/widmungskit", "/de/solarcarport", "/en/solarcarport",
  "/gebaeudestrom", "/parkplatz",
  "/ratgeber/solarpark-pacht-pro-hektar", "/newsletter", "/en/newsletter",
];
function last(re, html) { let m, out = null; while ((m = re.exec(html))) out = m; return out; }
for (const p of pages) {
  let res, html;
  for (let i = 0; i < 3; i++) {
    try { res = await fetch(BASE + p, { redirect: "manual" }); html = await res.text(); break; }
    catch (e) { await new Promise(r => setTimeout(r, 3000)); }
  }
  if (!res) { console.log(`${p}\tFETCH-FEHLER`); continue; }
  const status = res.status;
  const h1 = (html.match(/<h1[\s>]/g) || []).length;
  const titleM = last(/<title[^>]*>([^<]*)<\/title>/g, html);
  const title = titleM ? titleM[1] : "";
  const descM = last(/<meta name="description" content="([^"]*)"/g, html);
  const desc = descM ? descM[1] : "";
  const canonM = html.match(/<link rel="canonical" href="([^"]*)"/);
  const canon = canonM ? canonM[1] : "";
  const hreflang = (html.match(/hrefLang=|hreflang=/gi) || []).length;
  const robotsAll = [...html.matchAll(/<meta name="robots" content="([^"]*)"/g)].map(m => m[1]);
  let ldOk = true, ldN = 0;
  for (const m of html.matchAll(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)) {
    ldN++;
    try { JSON.parse(m[1]); } catch { ldOk = false; }
  }
  const probs = [];
  if (status !== 200) probs.push("STATUS=" + status);
  if (h1 !== 1) probs.push("H1=" + h1);
  if (!title) probs.push("KEIN-TITLE");
  if (title.length > 72) probs.push("TITLE-LANG=" + title.length);
  if (!desc) probs.push("KEINE-DESC");
  if (!canon) probs.push("KEIN-CANONICAL");
  if (!ldOk) probs.push("JSONLD-INVALID");
  console.log(`${p}\t${status}\th1=${h1}\tT=${title.length}\tD=${desc.length}\tcanon=${canon}\thl=${hreflang}\trobots=[${robotsAll.join("|")}]\tld=${ldN}${ldOk ? "" : "!"}\t${probs.length ? "PROBLEM: " + probs.join(",") : "OK"}`);
}

